"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["28703"],{28165(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.nome_obrigatorio","status":422,"titulo":"Nome do tipo de conceito \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.nome_obrigatorio","requisitos":[],"oQueAconteceu":["A cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) ou a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) de um tipo de conceito veio sem `nome`: o campo ausente, nulo, vazio ou s\xf3 com espa\xe7os. O corpo declara o nome como texto anul\xe1vel de prop\xf3sito, para que a aus\xeancia chegue \xe0 regra do dom\xednio e responda 422 com o c\xf3digo desta p\xe1gina, em vez de uma recusa gen\xe9rica de 400.","A recusa vem na lista `errors` da resposta, com `field` igual a `nome`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Informe o nome do tipo de conceito, com at\xe9 200 caracteres, e repita o pedido. A atualiza\xe7\xe3o envia o nome mesmo que ele n\xe3o mude, porque substitui a defini\xe7\xe3o do tipo por inteiro."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);